def scores(u, v):
    return {'personal': 4 - 0.6 * u - 0.6 * v, 'promotional': -2 + 0.9 * v - 0.1 * u, 'spam': -3 + 0.8 * u - 0.1 * v}

for point in [(1, 1), (2, 8), (7, 3)]:
    s = scores(*point)
    print(point, max(s, key=s.get))
# prints: (1, 1) personal
# prints: (2, 8) promotional
# prints: (7, 3) spam
